export const ICONS: readonly IconEntryType[] = ICON_PAIRS.map(([name, category]) => {
  return {
    name,
    category,
    categoryLabel: categoryLabel(category),
    label: iconLabel(name),
    tags: ICON_TAGS[`${category}/${name}`] ?? [],
    sizes: SIZE_OVERRIDES[`${category}/${name}`] ?? ALL_SIZES,
  };
});

export const ICON_CATEGORIES: readonly string[] = Array.from(new Set(ICONS.map((icon) => icon.category))).sort((a, b) =>
  categoryLabel(a).localeCompare(categoryLabel(b)),
);
